import{_ as r,l as c,o as a,c as n,v as o,p as s,x as d,d as i,i as l,S as p}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"整数溢出检测","description":"","frontmatter":{"title":"整数溢出检测","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/overflow-detect.md","filePath":"cs/overflow-detect.md","lastUpdated":1789023840000}'),_={name:"cs/overflow-detect.md"};function h(f,e,u,A,C,m){const t=c("Mermaid");return a(),n("div",null,[e[1]||(e[1]=o('<h1 id="整数溢出检测" tabindex="-1">整数溢出检测 <a class="header-anchor" href="#整数溢出检测" aria-label="Permalink to &quot;整数溢出检测&quot;">​</a></h1><div class="epigraph"><p>补码加减的溢出不是最高位进位本身，而是进位入与进位出是否一致；无符号则看那一位进位。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture；Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p><a href="/cs/fixed-point-dsp">上一课</a>把定点 MAC 写成宽累加再截位，但没说截位时如何知道「已经不能表示」。组成课的<a href="/cs/adder-cla">加法器</a>点过溢出接线，ALU 课也留了旗标口。缺口是把检测收成可用的硬件条件：有符号与无符号不同，乘除另算，供下一课饱和与后课 HDL 当控制。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n\\) 位补码可表示 \\([-2^{n-1},2^{n-1}-1]\\)。两正数相加得负，或两负数相加得正，即溢出：等价于最高位的进位入 \\(c_{n-1}\\) 与进位出 \\(c_n\\) 异或。无符号溢出就是 \\(c_n\\)。减法通过加反码走同一对进位。缺口不是再证补码表示，而是：<strong>旗标从哪根线来</strong>，以及 RISC-V 整数 <code>add</code> 默认不陷阱、软件要用 <code>add</code>/<code>sltu</code> 组合或分支去查。</p><p>定点 DSP 的累加器若宽于输出，溢出发生在<strong>截回输出宽度</strong>时，不是发生在宽加本身。</p><h3 id="进位不是溢出" tabindex="-1">进位不是溢出 <a class="header-anchor" href="#进位不是溢出" aria-label="Permalink to &quot;进位不是溢出&quot;">​</a></h3><p>无符号里进位≈溢出；有符号里 \\(c_n=1\\) 仍可能合法（例如 \\((-1)+(-1)\\) 得 \\(-2\\)，\\(c_n=1\\) 但未溢出）。把 FLAGS 的 Carry 与 Overflow 混用，条件跳会错。x86 的 <code>OF</code>/<code>CF</code> 分家，后课 ISA 对照会再看见；本课先钉布尔。</p><p><span class="marginnote">Harris 用 \\(c_n\\oplus c_{n-1}\\)。Patterson/Hennessy 强调 RISC-V 不因溢出陷入。本课不把 C 语言的未定义行为当硬件语义：硬件总给出模 \\(2^n\\) 的比特，检测是额外的位。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>加法器已有各位进位。引出 <code>V = c_n XOR c_{n-1}</code>（有符号），<code>C = c_n</code>（无符号）。乘：积的高半是否等于低半的符号扩展（有符号）或全 0（无符号）。除：除零与有符号 <code>min/-1</code>。FPU 的 overflow 是指数饱和，不要接到这对进位。</p>',11)),(a(),s(p,null,{default:d(()=>[l(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ADD%5B%22CLA%20%E5%90%84%E4%BD%8D%E8%BF%9B%E4%BD%8D%22%5D%20--%3E%20V%5B%22c_n%20XOR%20c_%7Bn-1%7D%20%E6%9C%89%E7%AC%A6%E5%8F%B7%22%5D%0A%20%20ADD%20--%3E%20C%5B%22c_n%20%E6%97%A0%E7%AC%A6%E5%8F%B7%22%5D%0A%20%20V%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E9%A5%B1%E5%92%8C%22%5D%0A%20%20C%20--%3E%20LATER%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>软件：RISC-V 用 <code>add t0,a0,a1</code> 再比较符号与操作数关系，或用更宽临时寄存器。硬件可选 <code>add</code> 写 <code>V</code> 到标志——ISA 选择。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>下一课饱和运算把 <code>V</code>/<code>C</code> 变成「钉在最大/最小可表示数」，而不是环绕。浮点<a href="/cs/fp-exceptions">异常</a>五位与这里的 <code>V</code> 分家：一个是 754 状态，一个是整数进位。后课 Verilog 里这两个位只是组合输出，不要用阻塞赋值在时钟边沿「补算」溢出，那是 HDL 课的坑。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不规定溢出必须陷阱（x86 <code>INTO</code> 是另一风格）。不讨论 saturating SIMD 指令表。不把密码学里的恒定时间溢出处理写成安全课。</p><p>后课默认：有符号溢出看最高两位进位异或；无符号看进位出；默认递送环绕结果加可选旗标。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>定点截位需要知道是否溢出；检测从加法器进位来。</li><li>有符号：<code>V=c_n⊕c_{n-1}</code>；无符号：<code>C=c_n</code>。</li><li>RISC-V <code>add</code> 不自动陷入；饱和是下一课的用法。</li><li>出处：Harris and Harris；Patterson and Hennessy, COD (RISC-V)。</li></ul>',8))])}const S=r(_,[["render",h]]);export{E as __pageData,S as default};
